p.me:
\begin{array}{ccl}
\text{estimate output change} \amp:\amp \Delta y\approx f'(x)\Delta x,\\
\text{estimate input change} \amp:\amp \Delta x\approx \dfrac{\Delta y}{f'(x)},\\
\text{estimate sensitivity} \amp:\amp \left|\dfrac{\Delta y}{\Delta x}\right|\approx |f'(x)|.
\end{array}
